content:
Help me define bounded contexts. Below I will provide domain information. 

#### Data:
These are the extracted objects and the subdomain grouping:
```json
{
  "domain objects": [
    {
      "name": "Author",
      "description": "A writer who creates and submits manuscripts for publication."
    },
    {
      "name": "Book",
      "description": "A completed and published work based on an author’s manuscript.",
      "attributes": [
        "Final Proof",
        "Author",
        "Publisher"
      ]
    },
    {
      "name": "Final Proof",
      "description": "The finalized version of a book prepared for printing."
    },
    {
      "name": "Publisher",
      "description": "An organization that approves, funds, and manages book production."
    },
    {
      "name": "Manuscript",
      "description": "The original written work produced by the author."
    },
    {
      "name": "Manuscript Submission",
      "description": "A document package containing the author’s manuscript sent for editorial review.",
      "attributes": [
        "Manuscript"
      ]
    },
    {
      "name": "Editorial Approval",
      "description": "An editor’s confirmation that a manuscript is ready for publishing."
    },
    {
      "name": "Editor",
      "description": "A professional who reviews manuscripts and provides editorial feedback."
    },
    {
      "name": "Editorial Feedback",
      "description": "Comments and suggestions from the editor to improve the manuscript."
    },
    {
      "name": "Publishing Submission",
      "description": "The author’s request to publish the final proof through the publisher.",
      "attributes": [
        "Final Proof"
      ]
    },
    {
      "name": "Budget",
      "description": "Funds allocated by the publisher to support the publication process."
    },
    {
      "name": "Print Job",
      "description": "An order created by the publisher to print copies of a finished book.",
      "attributes": [
        "Book"
      ]
    },
    {
      "name": "Contract",
      "description": "A formal agreement defining rights and responsibilities between the author and publisher."
    }
  ]
}
```
```json
{
  "subdomains": {
    "Publishing": {
      "objects": [
        "Publisher",
        "Budget",
        "Print Job",
        "Book",
        "Author",
        "Final Proof"
      ]
    },
    "Submission": {
      "objects": [
        "Final Proof",
        "Publishing Request",
        "Publisher",
        "Contract",
        "Author"
      ]
    },
    "Editing": {
      "objects": [
        "Author",
        "Manuscript Submission",
        "Manuscript",
        "Editor",
        "Editorial Approval",
        "Editorial Feedback"
      ]
    }
  }
}
```

Here are the bounded contexts: 
```json
{
  "bounded contexts": {
    "Publishing": {
      "derived from": "Publishing Subdomain",
      "objects": [
        "Production Publisher",
        "Budget",
        "Print Job",
        "Book",
        "Book Author",
        "Book Manuscript"
      ],
      "name changes": [
        "Publisher -> Production Publisher",
        "Author -> Book Author",
        "Final Proof -> Book Manuscript"
      ]
    },
    "Submission": {
      "derived from": "Submission Subdomain",
      "objects": [
        "Final Proof",
        "Publishing Request",
        "Publisher",
        "Contract",
        "Applicant Author"
      ],
      "name changes": [
        "Author -> Applicant Author"
      ]
    },
    "Editing": {
      "derived from": "Editing Subdomain",
      "objects": [
        "Author",
        "Manuscript Submission",
        "Manuscript",
        "Editor",
        "Editorial Approval",
        "Editorial Feedback"
      ],
      "name changes": []
    }
  }
}
```
